// ============================================================
// REGRA DE NEGÓCIO: Cruzamento perfil + saldo mínimo
// ============================================================

const item = $input.first().json;
const cliente = item.cliente || item;

// Normaliza perfil
const perfil = String(cliente.perfil || 'Moderado').trim();

// Normaliza saldo (suporta R$ 1.234,56 / 1234.56 / etc)
let saldoRaw = String(cliente.saldo || '0');
saldoRaw = saldoRaw.replace(/[^\d,.-]/g, '');
if (saldoRaw.includes(',') && saldoRaw.includes('.')) {
  saldoRaw = saldoRaw.replace(/\./g, '').replace(',', '.');
} else if (saldoRaw.includes(',')) {
  saldoRaw = saldoRaw.replace(',', '.');
}
const saldo = parseFloat(saldoRaw) || 0;

// Carrega investimentos do nó Parse CSV ou fallback embutido
let investimentos = [];
try {
  investimentos = $('Parse CSV Investimentos').all().map(i => ({
    perfil: String(i.json.perfil || '').trim(),
    produto: String(i.json.produto || '').trim(),
    minimo: parseInt(String(i.json.minimo || '0').replace(/\D/g, ''), 10) || 0,
    rentabilidade: String(i.json.rentabilidade || '').trim(),
  }));
} catch (err) {
  // Catalogo de contingencia
  investimentos = [
    { perfil: 'Conservador', produto: 'Poupança', minimo: 100, rentabilidade: '6.2%' },
    { perfil: 'Conservador', produto: 'CDB Liquidez Diária', minimo: 1000, rentabilidade: '12.5%' },
    { perfil: 'Conservador', produto: 'Tesouro Selic', minimo: 500, rentabilidade: '13.0%' },
    { perfil: 'Moderado', produto: 'CDB Prefixado', minimo: 1000, rentabilidade: '14.0%' },
    { perfil: 'Moderado', produto: 'Fundo Multimercado', minimo: 5000, rentabilidade: '16.0%' },
    { perfil: 'Moderado', produto: 'Tesouro IPCA+', minimo: 1000, rentabilidade: 'IPCA+6.0%' },
    { perfil: 'Arrojado', produto: 'Ações ETF', minimo: 500, rentabilidade: 'Variável' },
    { perfil: 'Arrojado', produto: 'Fundo de Ações', minimo: 10000, rentabilidade: 'Variável' },
    { perfil: 'Arrojado', produto: 'Criptomoedas', minimo: 100, rentabilidade: 'Variável' }
  ];
}

// Filtra por perfil e saldo mínimo
const doPerfil = investimentos.filter(i => i.perfil.toLowerCase() === perfil.toLowerCase());
const compativeis = doPerfil
  .filter(i => saldo >= i.minimo)
  .sort((a, b) => a.minimo - b.minimo);

// Mensagens estáticas por perfil (MVP)
const intros = {
  'Conservador': 'foco em segurança e preservação de capital',
  'Moderado': 'equilíbrio entre segurança e rentabilidade',
  'Arrojado': 'potencial de retorno elevado com maior exposição a risco',
};

let mensagem;
if (compativeis.length === 0) {
  mensagem = `Olá ${cliente.nome}, identificamos seu perfil ${perfil}, mas seu saldo atual (R$ ${saldo.toFixed(2)}) ainda não atinge o mínimo exigido para as opções disponíveis. Recomendamos aguardar ou aportar valores adicionais.`;
} else {
  const produtos = compativeis.map(i => ` • ${i.produto} — ${i.rentabilidade} (mín. R$ ${i.minimo})`).join('\n');
  mensagem = `Olá ${cliente.nome}, com base no seu perfil ${perfil} (${intros[perfil] || ''}) e saldo de R$ ${saldo.toFixed(2)}, recomendamos:\n${produtos}`;
}

return [{
  json: {
    nome: cliente.nome,
    email: cliente.email || '',
    perfil: perfil,
    saldo: saldo,
    investimentos_recomendados: compativeis,
    mensagem_estatica: mensagem,
    mensagem: mensagem,
    fonte: 'n8n-code-node'
  }
}];

// Fallback: retorna mensagem estática caso a IA falhe (timeout, rate limit ou falta de credencial)
const item = $input.first().json;
return [{
  json: {
    ...item,
    mensagem: item.mensagem_estatica || item.mensagem,
    observacao: 'Mensagem estática usada como fallback por falha na IA.'
  }
}];
